<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, reactive, ref, watch } from 'vue';
import { useDisplay } from 'vuetify';
import { api } from '../lib/api';
import { manageableGroups, groupLabel } from '../lib/permissions';
import { previewUrl, type FileAsset, type PersonalRecord, type UserWithProfile } from '../lib/platform';
import { certificateKeys, type CertificateField, type CertificateKey, type CertificateTemplate } from '../lib/certificates';
const emit = defineEmits<{close:[]; issued:[number]}>();
const {smAndDown}=useDisplay();
const templates=ref<CertificateTemplate[]>([]),users=ref<UserWithProfile[]>([]),selected=ref<CertificateTemplate|null>(null);
const loading=ref(true),busy=ref(false),error=ref(''),notice=ref(''),step=ref(1);
const source=ref<File|null>(null),templateName=ref(''),fields=ref<CertificateField[]>([]),selectedFieldId=ref(''),page=ref(0),addKey=ref<CertificateKey>('name');
const search=ref(''),recipientIds=ref<string[]>([]),previewUserId=ref(''),previewImage=ref(''),previewSignature=ref(''),confirmed=ref(false),issueConfirm=ref(false),batchRequestId=ref(''),batchPayload=ref('');
const values=ref<Record<string,string>>({});
const issue=reactive({title:'',kind:'certificate',description:'',direction:'',date:new Date().toLocaleDateString('en-CA')});
const field=computed(()=>fields.value.find(f=>f.id===selectedFieldId.value));
const sheet=computed(()=>selected.value?.pages[page.value]);
const canvasElement=ref<HTMLElement|null>(null),canvasWidth=ref(760);
let observer:ResizeObserver|undefined;
watch(canvasElement,el=>{observer?.disconnect();if(el){observer=new ResizeObserver(entries=>{canvasWidth.value=entries[0]?.contentRect.width||760;});observer.observe(el);}});
onBeforeUnmount(()=>observer?.disconnect());
const keyTitle=(key:string)=>certificateKeys.find(k=>k.value===key)?.title||key;
const issuanceGroups=computed(()=>manageableGroups('records'));
const eligibleUsers=computed(()=>users.value.filter(u=>!issue.direction||u.eligibleDirections?.includes(issue.direction)));
const filteredUsers=computed(()=>eligibleUsers.value.filter(u=>`${u.name} ${u.email} ${u.profile?.studentNumber||''} ${(u.eligibleDirections||[]).map(groupLabel).join(' ')}`.toLowerCase().includes((search.value||'').trim().toLowerCase())));
watch(()=>issue.direction,()=>{const allowed=new Set(eligibleUsers.value.map(u=>u.id));const previous=recipientIds.value.length;recipientIds.value=recipientIds.value.filter(id=>allowed.has(id));if(previous!==recipientIds.value.length)notice.value='已按所选组别移除不符合条件的接收人，请重新核对名单。';});
const currentSignature=computed(()=>JSON.stringify({template:selected.value?.id,templateVersion:selected.value?.updatedAt,fields:fields.value,userId:previewUserId.value,page:page.value,issue:{...issue},recipients:recipientIds.value}));
const canIssue=computed(()=>!!previewImage.value&&previewSignature.value===currentSignature.value&&confirmed.value&&recipientIds.value.length>0&&recipientIds.value.length<=50&&!!issue.title.trim());
watch(currentSignature,()=>{confirmed.value=false;});
watch(recipientIds,ids=>{if(!ids.includes(previewUserId.value))previewUserId.value=ids[0]||'';});
function chooseTemplate(template:CertificateTemplate){selected.value=template;fields.value=(template.fields||[]).map(f=>({...f}));templateName.value=template.name;issue.title=template.name;page.value=0;selectedFieldId.value=fields.value[0]?.id||'';previewImage.value='';previewSignature.value='';error.value='';step.value=2;}
async function load(){loading.value=true;error.value='';try{const [t,u]=await Promise.all([api.get<{items:CertificateTemplate[]}>('/certificate-templates'),api.get<{items:UserWithProfile[]}>('/users?permission=records')]);templates.value=t.items;users.value=u.items;}catch(e){error.value=(e as Error).message;}finally{loading.value=false;}}
async function importTemplate(){if(!source.value||busy.value)return;if(source.value.size>25*1024*1024){error.value='证书底稿不能超过 25 MB。';return;}if(!/\.(pdf|docx|png|jpe?g)$/i.test(source.value.name)){error.value='请选择 PDF、DOCX、PNG 或 JPEG 模板。';return;}busy.value=true;error.value='';try{const data=new FormData();data.append('file',source.value);const uploaded=await api.upload<{item:FileAsset}>('/files',data);const result=await api.post<{item:CertificateTemplate}>('/certificate-templates',{name:templateName.value.trim()||source.value.name.replace(/\.[^.]+$/,''),sourceFileId:uploaded.item.id});templates.value.unshift(result.item);chooseTemplate(result.item);source.value=null;}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
function addField(){const f:CertificateField={id:crypto.randomUUID(),key:addKey.value,text:addKey.value==='text'?'请填写文字':undefined,page:page.value,x:.25,y:.4,width:.5,fontSize:24,align:'center',color:'#202a35'};fields.value.push(f);selectedFieldId.value=f.id;}
function fieldStyle(f:CertificateField){const size=sheet.value?f.fontSize*canvasWidth.value/sheet.value.width:16;return{left:`${f.x*100}%`,top:`${f.y*100}%`,width:`${f.width*100}%`,fontSize:`${size}px`,textAlign:f.align,color:f.color};}
function placeField(event:MouseEvent){if(busy.value||!field.value||!canvasElement.value||event.target!==event.currentTarget&&!(event.target instanceof HTMLImageElement))return;const rect=canvasElement.value.getBoundingClientRect();field.value.x=Math.max(0,Math.min(1-field.value.width,(event.clientX-rect.left)/rect.width));field.value.y=Math.max(0,Math.min(.95,(event.clientY-rect.top)/rect.height));field.value.page=page.value;}
let drag:{id:string;x:number;y:number;startX:number;startY:number;width:number;height:number}|null=null;
function beginDrag(event:PointerEvent,f:CertificateField){if(busy.value)return;selectedFieldId.value=f.id;const box=canvasElement.value?.getBoundingClientRect();if(!box)return;drag={id:f.id,x:f.x,y:f.y,startX:event.clientX,startY:event.clientY,width:box.width,height:box.height};(event.currentTarget as HTMLElement).setPointerCapture(event.pointerId);}
function moveDrag(event:PointerEvent){if(!drag)return;const f=fields.value.find(f=>f.id===drag!.id);if(!f)return;f.x=Math.max(0,Math.min(1-f.width,drag.x+(event.clientX-drag.startX)/drag.width));f.y=Math.max(0,Math.min(.95,drag.y+(event.clientY-drag.startY)/drag.height));}
function setPercent(key:'x'|'y'|'width',value:unknown){if(!field.value)return;const n=Number(value)/100;if(Number.isFinite(n))field.value[key]=n;}
async function saveTemplate(){if(!selected.value)return;const data=await api.patch<{item:CertificateTemplate}>(`/certificate-templates/${selected.value.id}`,{name:templateName.value.trim(),fields:fields.value});selected.value=data.item;templates.value=templates.value.map(t=>t.id===data.item.id?data.item:t);}
async function next(){if(!fields.value.length){error.value='请至少添加姓名或其他填写区域。';return;}busy.value=true;error.value='';try{await saveTemplate();step.value=3;}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
function selectMatching(){const matches=[...new Set([...recipientIds.value,...filteredUsers.value.map(u=>u.id)])];recipientIds.value=matches.slice(0,50);if(matches.length>50)notice.value='每批最多 50 人，已选择前 50 位接收人，剩余成员请分批发放。';}
function issuedAt(){return issue.date?new Date(issue.date+'T12:00:00+08:00').toISOString():'';}
async function preview(){if(!selected.value||!previewUserId.value||busy.value)return;busy.value=true;error.value='';previewImage.value='';try{await saveTemplate();const signature=currentSignature.value;const result=await api.post<{previewDataUrl:string;values:Record<string,string>}>(`/certificate-templates/${selected.value.id}/preview`,{userId:previewUserId.value,direction:issue.direction,issuedAt:issuedAt(),fields:fields.value,page:page.value});if(signature===currentSignature.value){previewImage.value=result.previewDataUrl;values.value=result.values;previewSignature.value=signature;}}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
async function send(){if(!selected.value||!canIssue.value||busy.value)return;const body={templateId:selected.value.id,templateVersion:selected.value.updatedAt,userIds:recipientIds.value,title:issue.title,kind:issue.kind,description:issue.description,direction:issue.direction,issuedAt:issuedAt()};const signature=JSON.stringify(body);if(signature!==batchPayload.value){batchPayload.value=signature;batchRequestId.value=crypto.randomUUID();}busy.value=true;error.value='';issueConfirm.value=false;try{const result=await api.post<{items:PersonalRecord[]}>('/certificate-batches',{...body,requestId:batchRequestId.value});emit('issued',result.items.length);}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
onMounted(load);
</script>

<template>
<v-dialog :model-value="true" max-width="1180" :fullscreen="smAndDown" persistent scrollable>
  <v-card class="certificate-studio">
    <v-card-title class="studio-heading"><div><h2>证书模板与批量发放</h2><p>上传底稿，设置填写区域，按成员资料生成专属证书。</p></div><v-btn icon="mdi-close" variant="text" aria-label="关闭证书工作台" :disabled="busy" @click="emit('close')"/></v-card-title>
    <v-tabs v-model="step" color="primary" class="studio-steps" :disabled="busy"><v-tab :value="1">1 · 选择模板</v-tab><v-tab :value="2" :disabled="!selected">2 · 编辑填写区域</v-tab><v-tab :value="3" :disabled="!selected||!fields.length">3 · 预览与发放</v-tab></v-tabs>
    <v-card-text class="studio-body">
      <v-alert v-if="error" type="error" variant="tonal" class="mb-4">{{error}}<v-btn v-if="!selected" variant="text" :disabled="busy||loading" @click="load">重试加载</v-btn></v-alert>
      <v-progress-linear v-if="busy||loading" indeterminate color="primary" class="mb-3"/>
      <p v-if="busy" class="text-body-2 text-medium-emphasis">正在处理，请等待完成后关闭窗口。</p>
      <template v-if="step===1">
        <div class="template-intro"><v-icon size="34" color="primary">mdi-certificate-outline</v-icon><div><h3>把证书底稿变成可重复使用的模板</h3><p>支持 PDF、Word（DOCX）、PNG 和 JPEG，最多 5 页、25 MB。请为姓名、组别等保留空白位置；Word 会先转换为 PDF。</p></div></div>
        <v-card variant="outlined" class="pa-5 mb-6"><v-text-field v-model="templateName" label="模板名称" :disabled="busy"/><v-file-input v-model="source" label="上传证书底稿" accept=".pdf,.docx,.png,.jpg,.jpeg" show-size :disabled="busy"/><v-btn color="primary" prepend-icon="mdi-upload" :disabled="!source||busy" :loading="busy" @click="importTemplate">导入模板并编辑</v-btn></v-card>
        <h3 class="mb-3">已有模板</h3><div v-if="templates.length" class="template-grid"><button v-for="t in templates" :key="t.id" class="template-card" :disabled="busy" @click="chooseTemplate(t)"><img :src="previewUrl(t.pages[0]!.previewFileId)" :alt="t.name"/><strong>{{t.name}}</strong><span>{{t.pages.length}} 页 · {{t.fields.length}} 个填写区域</span></button></div><p v-else class="text-medium-emphasis">还没有模板，上传第一份底稿开始。</p>
      </template>
      <template v-else-if="selected&&step===2">
        <div class="editor-toolbar"><v-text-field v-model="templateName" label="模板名称" hide-details :disabled="busy"/><v-select v-model="page" :items="selected.pages.map((_,i)=>({title:`第 ${i+1} 页`,value:i}))" label="页面" hide-details :disabled="busy"/></div>
        <p class="studio-hint">添加字段后可拖动定位，也可点击底稿放置当前字段。页面上的方框只用于编辑，最终证书不显示方框；请在发放前查看真实预览。</p>
        <div class="editor-grid">
          <div class="sheet-wrap"><div ref="canvasElement" class="certificate-sheet" :style="{aspectRatio:sheet?`${sheet.width}/${sheet.height}`:undefined}" @click="placeField"><img v-if="sheet" :src="previewUrl(sheet.previewFileId)" alt="证书模板底稿" draggable="false"/><button v-for="f in fields.filter(f=>f.page===page)" :key="f.id" type="button" :aria-label="`定位${keyTitle(f.key)}字段`" class="certificate-field" :class="{selected:f.id===selectedFieldId}" :style="fieldStyle(f)" :disabled="busy" @pointerdown.stop="beginDrag($event,f)" @pointermove="moveDrag" @pointerup="drag=null" @pointercancel="drag=null" @click.stop="selectedFieldId=f.id">{{ f.key === 'text' ? f.text : '〔' + keyTitle(f.key) + '〕' }}</button></div></div>
          <aside class="field-editor"><h3>填写区域</h3><div class="d-flex ga-2 align-center"><v-select v-model="addKey" :items="certificateKeys" label="自动填写内容" hide-details :disabled="busy"/><v-btn color="primary" icon="mdi-plus" aria-label="添加填写区域" :disabled="busy" @click="addField"/></div><v-select v-if="fields.length" v-model="selectedFieldId" :items="fields.map((f,i)=>({title:`${i+1}. ${keyTitle(f.key)} · 第${f.page+1}页`,value:f.id}))" label="正在编辑" class="mt-4" :disabled="busy"/>
            <template v-if="field"><v-textarea v-if="field.key==='text'" v-model="field.text" label="自定义文字" rows="2" :disabled="busy"/><div class="field-position"><v-text-field :model-value="Math.round(field.x*1000)/10" type="number" label="左边距 %" min="0" max="100" :disabled="busy" @update:model-value="setPercent('x',$event)"/><v-text-field :model-value="Math.round(field.y*1000)/10" type="number" label="上边距 %" min="0" max="95" :disabled="busy" @update:model-value="setPercent('y',$event)"/><v-text-field :model-value="Math.round(field.width*1000)/10" type="number" label="区域宽度 %" min="1" max="100" :disabled="busy" @update:model-value="setPercent('width',$event)"/><v-text-field v-model.number="field.fontSize" type="number" label="字号 pt" min="8" max="96" :disabled="busy"/></div><v-select v-model="field.align" :items="[{title:'左对齐',value:'left'},{title:'居中',value:'center'},{title:'右对齐',value:'right'}]" label="文字对齐" :disabled="busy"/><label class="color-control">文字颜色<input v-model="field.color" type="color" :disabled="busy"/></label><v-btn variant="text" color="error" prepend-icon="mdi-delete-outline" :disabled="busy" @click="fields=fields.filter(f=>f.id!==selectedFieldId);selectedFieldId=fields[0]?.id||''">删除此区域</v-btn></template><p v-else class="studio-hint">先添加“姓名”等字段，再设置位置。</p>
          </aside>
        </div><div class="studio-footer"><span>长文字会适当缩小以适应区域。</span><v-btn color="primary" append-icon="mdi-arrow-right" :disabled="busy||!fields.length" @click="next">保存模板，选择接收人</v-btn></div>
      </template>
      <template v-else-if="selected&&step===3">
        <div class="issuance-grid"><section><h3 class="mb-4">发放信息</h3><v-text-field v-model="issue.title" label="证书标题 *" :disabled="busy" maxlength="100"/><v-row><v-col cols="6"><v-select v-model="issue.kind" :items="[{title:'奖状证书',value:'certificate'},{title:'荣誉奖励',value:'award'},{title:'个人通知',value:'notice'}]" label="类型" :disabled="busy"/></v-col><v-col cols="6"><v-text-field v-model="issue.date" label="发放日期" type="date" :disabled="busy"/></v-col></v-row><v-select v-model="issue.direction" :items="[{title:'使用各自已加入的组',value:''},...issuanceGroups]" label="证书上的组别" hint="指定组别时，仅能向该组有效成员发放。" persistent-hint :disabled="busy"/><v-textarea v-model="issue.description" label="证书说明（选填）" rows="2" class="mt-4" :disabled="busy"/><h3>接收人 <span class="text-primary">{{recipientIds.length}} / 50</span></h3><v-text-field v-model="search" label="搜索姓名、邮箱或学号" prepend-inner-icon="mdi-magnify" hide-details class="my-3" :disabled="busy"/><div class="d-flex ga-2 mb-2"><v-btn variant="text" size="small" :disabled="busy" @click="selectMatching">选择搜索结果</v-btn><v-btn variant="text" size="small" :disabled="busy" @click="recipientIds=[]">清空选择</v-btn></div><div class="recipient-list"><v-checkbox v-for="u in filteredUsers" :key="u.id" v-model="recipientIds" :value="u.id" :label="`${u.name} · ${u.profile?.studentNumber||u.email}`" :disabled="busy||recipientIds.length>=50&&!recipientIds.includes(u.id)" hide-details density="compact"/><p v-if="!filteredUsers.length" class="pa-3 text-medium-emphasis">没有匹配的接收人。</p></div></section>
        <section class="preview-panel"><h3>真实生成预览</h3><p class="studio-hint">选择一位接收人查看实际效果。字段、接收人或发放信息变更后，需要重新预览。</p><v-select v-model="previewUserId" :items="users.filter(u=>recipientIds.includes(u.id)).map(u=>({title:u.name,value:u.id}))" label="预览接收人" :disabled="busy"/><v-select v-if="selected.pages.length>1" v-model="page" :items="selected.pages.map((_,i)=>({title:`第 ${i+1} 页`,value:i}))" label="预览页面" :disabled="busy"/><v-btn color="primary" variant="tonal" prepend-icon="mdi-eye-outline" :disabled="busy||!previewUserId" @click="preview">生成预览</v-btn><img v-if="previewImage" class="generated-preview" :class="{stale:previewSignature!==currentSignature}" :src="previewImage" alt="按成员资料生成的证书预览"/><div v-else class="preview-placeholder"><v-icon size="42" color="grey-lighten-1">mdi-file-certificate-outline</v-icon><p>生成预览后，证书将显示在这里。</p></div><v-alert v-if="previewImage&&previewSignature!==currentSignature" type="info" density="compact" variant="tonal">内容已变更，请重新生成预览。</v-alert><v-checkbox v-model="confirmed" label="已核对预览、发放信息和接收人" :disabled="busy||!previewImage||previewSignature!==currentSignature" hide-details/><p class="studio-hint">每位成员获得独立的 PDF 和可预览图片，保存到其荣誉中心。</p></section></div>
        <div class="studio-footer"><v-btn variant="text" :disabled="busy" @click="step=2">返回调整模板</v-btn><v-btn color="primary" prepend-icon="mdi-send-outline" :disabled="busy||!canIssue" @click="issueConfirm=true">批量生成并发放（{{recipientIds.length}} 人）</v-btn></div>
      </template>
    </v-card-text>
  </v-card>
  <v-dialog v-model="issueConfirm" max-width="480"><v-card title="确认发放证书"><v-card-text>将为 {{recipientIds.length}} 位成员生成“{{issue.title}}”，分别放入各自荣誉中心。<p class="mt-3 text-medium-emphasis">任一成员资料不完整或生成失败时，整批不会发放，可修正后重试。</p></v-card-text><v-card-actions><v-spacer/><v-btn @click="issueConfirm=false">返回检查</v-btn><v-btn color="primary" @click="send">确认生成并发放</v-btn></v-card-actions></v-card></v-dialog>
  <v-snackbar :model-value="!!notice" @update:model-value="!$event&&(notice='')">{{notice}}</v-snackbar>
</v-dialog>
</template>

<style scoped>
.studio-heading{display:flex;align-items:flex-start;gap:20px;padding:22px 26px;white-space:normal}.studio-heading>div{flex:1;min-width:0}.studio-heading h2{font-size:21px;font-weight:500}.studio-heading p{font-size:13px;color:#72808b;margin:7px 0 0}.studio-steps{flex-shrink:0;border-bottom:1px solid #e6ebef}.studio-body{padding:24px!important}.template-intro{display:flex;gap:18px;margin:8px 0 24px}.template-intro h3,.field-editor h3,.issuance-grid h3{font-size:16px;font-weight:500}.template-intro p{font-size:13px;line-height:1.8;color:#697987;margin:8px 0 0}.template-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px}.template-card{text-align:left;background:#fff;border:1px solid #dce4eb;border-radius:5px;padding:12px;display:flex;flex-direction:column;gap:8px}.template-card:hover{border-color:#1976d2}.template-card img{width:100%;height:140px;object-fit:contain;background:#f4f6f9}.template-card strong{font-size:14px;font-weight:500;overflow-wrap:anywhere}.template-card span{font-size:12px;color:#71808c}.editor-toolbar{display:grid;grid-template-columns:1fr 170px;gap:24px}.studio-hint{font-size:12px;line-height:1.8;color:#6a7d8d;margin:12px 0}.editor-grid{display:grid;grid-template-columns:minmax(0,1fr) 270px;gap:24px;align-items:start}.sheet-wrap{background:#edf1f6;padding:14px;border-radius:5px;overflow:hidden}.certificate-sheet{position:relative;width:100%;background:#fff;box-shadow:0 3px 12px #18243816;overflow:hidden}.certificate-sheet>img{display:block;width:100%;height:100%;pointer-events:none}.certificate-field{position:absolute;display:block;line-height:1.2;background:#e8f2ff99;border:1px dashed #598ac6;white-space:nowrap;overflow:hidden;padding:0;touch-action:none;cursor:move;min-height:20px}.certificate-field.selected{outline:2px solid #1976d2;outline-offset:1px;background:#c5e4ffb3}.field-editor{min-width:0}.field-editor>h3{margin-bottom:18px}.field-position{display:grid;grid-template-columns:1fr 1fr;gap:6px}.color-control{display:flex;align-items:center;justify-content:space-between;font-size:13px;color:#596d7c;margin-bottom:14px}.color-control input{width:64px;height:30px}.studio-footer{display:flex;align-items:center;justify-content:space-between;gap:18px;border-top:1px solid #e6ebef;padding-top:22px;margin-top:24px;flex-wrap:wrap}.studio-footer>span{font-size:12px;color:#778797}.issuance-grid{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:30px}.recipient-list{max-height:290px;overflow:auto;border:1px solid #e2e8ee;border-radius:4px;padding:8px}.recipient-list :deep(.v-label){white-space:normal;overflow-wrap:anywhere;font-size:13px}.preview-panel{background:#f8fafc;border:1px solid #e3eaf1;border-radius:5px;padding:20px}.generated-preview{width:100%;margin-top:20px;box-shadow:0 2px 12px #18314716}.generated-preview.stale{opacity:.5}.preview-placeholder{min-height:220px;display:flex;flex-direction:column;align-items:center;justify-content:center;color:#87939e;font-size:13px}.preview-placeholder p{margin-top:14px}@media(max-width:800px){.editor-grid,.issuance-grid{grid-template-columns:1fr}.template-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.studio-body{padding:16px!important}.studio-heading{padding:18px}.studio-heading h2{font-size:18px}.editor-toolbar{grid-template-columns:1fr 110px;gap:12px}.studio-footer .v-btn{max-width:100%}}
</style>
